WITH src AS (SELECT * FROM payments WHERE order_id IN (20, 33, 37) AND status IN ('FAILED', 'SUCCESS', 'REFUNDED')), Summary AS (SELECT CASE WHEN amount >= 1260 THEN 'high' WHEN amount >= 750 THEN 'mid' ELSE 'low' END amount_bucket, COUNT(DISTINCT amount) unique_methods FROM src GROUP BY CASE WHEN amount >= 1260 THEN 'high' WHEN amount >= 750 THEN 'mid' ELSE 'low' END) SELECT amount_bucket, unique_methods FROM Summary WHERE unique_methods < 5 ORDER BY amount_bucket;
